            9, -2, 4, -1, -8, 4, 3, -2, -4, 3, 2, -4, 5, 12, -8, -5,
            20, -14, 7, 6, -8, 11, 14, 0, -3, 2, -2, 5, 12, 2, -7, -6,
            0, -11, -8, 2, -7, 0, -6, 9, -4, 8, 7, 0, -12, 5, 0, -2,
            9, 0, -8, -1, -16, -4, -5, 10, -2, -3, 6, 2, -7, 6, 2, -1,
