            2, 1, -4, 12, 1, 8, 14, -7, 8, 14, 7, -6, -14, 7, 6, 0,
            3, -10, -6, 1, -16, 0, 1, 0, 4, 3, -6, -2, 5, -6, -6, 7,
            -6, -8, 9, 6, -8, 5, -2, 10, 3, 6, -8, -5, 8, -12, 3, 0,
            18, 3, 16, -2, -11, 0, 8, -1, 10, 8, -5, -12, -4, -5, -2, 8,
            -1, 8, -4, -7, -4, 0, 3, 14, -6, 9, 2, 4, 9, 0, -10, 15
        ),
        2 => (
            -8, 13, -6, -2, 1, 4, -4, -9, -6, 2, 5, -2, -12, 1, -2, 6,
            -1, 2, 8, 7, 12, 4, -3, -8, 2, 9, -2, 6, 13, -4, -8, 1,
            2, -8, 9, 4, 6, -5, 6, 2, -1, 12, 4, -5, -6, -2, -5, -6,
            6, 3, 4, 4, -1, 8, 0, 9, -10, 2, 9, -6, 6, 1, 8, -4,
            -5, -12, 18, -5, -2, -8, -5, 12, 4, -7, 8, 4, 3, 6, -10, 13,
            -6, 0, -3, 0, 18, -1, 10, 6, 5, 6, -8, 1, 10, 2, -3, 18,
            0, -3, 2, -8, -3, 8, 12, 3, -16, 20, -11, -10, 22, 7, 4, 4,
            -7, -6, 0, -5, -2, 4, 5, 2, -4, 3, -8, -10, 1, -2, 12, 3,
            -4, 0, -1, 2, 4, 11, 4, -2, 9, 8, 4, -3, 0, 2, 9, 4,
            2, 9, 10, -8, -1, 10, -4, 15, 16, 2, 11, 4, -2, -1, -10, 16,
            1, 6, 0, -3, -2, -2, -1, -2, 2, 5, 0, -4, 7, -12, -4, 11,
            -6, -2, 1, -8, 0, 9, -10, 0, -1, 4, 2, -9, 6, -2, 9, 2,
            0, 23, 2, -10, 11, -4, -2, 15, 0, 4, -1, 12, 6, 7, 4, -2,
            -11, 18, 2, 3, 20, -18, -9, 10, 2, 5, 10, 4, 1, 2, 4, -11,
            -10, 2, -3, 0, 6, -9, -6, 0, -1, 0, 8, -7, 10, -6, 7, -2,
            -2, 7, 10, 0, 1, 8, 16, 11, -6, 8, -1, 12, 8, -3, 0, 20,
            -7, 10, -2, 11, 6, -8, 1, 6, 2, 7, 6, -20, 7, 0, -10, 15,
            6, 2, -3, -8, 16, -3, 0, 0, -7, -12, -8, -5, 14, 2, 5, -6,
            4, -9, -4, -10, 21, -6, -2, 9, -6, -10, -3, 10, 16, 5, 14, 0,
            -1, -10, 8, 7, 0, -6, 1, 12, -6, 5, -4, -4, 9, 14, -14, 7,
            -8, 6, 3, -6, -12, 11, 0, -14, -7, 10, -4, -13, 10, -6, -3, 10,
            -8, -1, 6, -12, -5, -2, 2, -5, 4, 4, 3, -2, 2, 3, 8, 12,
            -5, 4, -2, 5, 10, -2, 1, 4, 6, 1, 0, 6, -1, -10, 10, 9,
            -18, 16, -3, -4, 10, -7, -12, 2, 7, 0, 4, -1, -10, 0, 11, 8,
            2, 15, 10, 0, 11, 2, 8, -5, 6, -6, -3, 2, 14, -1, 2, 4,
            -5, 2, 10, 5, 18, 6, 9, -8, 4, 7, -4, 0, 11, -4, 0, 5,
            -4, 12, -1, -6, -4, -3, -10, 12, -3, -8, 6, 5, -10, -8, 1, 4,
            0, 3, 6, -10, 3, -6, -12, 11, -6, -12, -3, 8, 16, -3, -4, 2,
            1, 12, 8, 3, 18, 2, 3, 2, -2, 1, 8, 4, -1, 8, 8, -3,
            8, 10, -5, -4, 10, -1, 4, -8, 1, -4, 10, 9, -6, 14, 1, 2,
            -16, 1, -14, 4, 15, 2, -6, 5, -8, -6, 9, 14, 6, 9, 4, -6,
            5, -6, 6, 11, 6, 2, 1, -12, 8, -5, 0, -2, -5, 2, 12, -11
        )
    );
    -- END GENERATED REBUILD VECTORS

    signal clk            : std_logic := '0';
    signal rst_n          : std_logic := '0';
    signal start          : std_logic := '0';
    signal data_in_valid  : std_logic := '0';
    signal done           : std_logic;
    signal data_q00       : std_logic_vector(C_DATA_WIDTH - 1 downto 0) :=
                            (others => '0');
    signal data_q01       : std_logic_vector(C_DATA_WIDTH - 1 downto 0) :=
                            (others => '0');
    signal data_w1        : std_logic_vector(C_DATA_WIDTH - 1 downto 0) :=
                            (others => '0');
    signal data_h0        : std_logic_vector(C_NUM_SAMPLES - 1 downto 0) :=
                            (others => '0');
    signal data_out       : std_logic_vector(C_DATA_WIDTH - 1 downto 0);
    signal data_out_valid : std_logic;
    signal dut_error      : std_logic;

    function h0_test_1(index : natural) return std_logic is
    begin
        if (index mod 3) = 0 or (index mod 11) = 0 then
            return '1';
        end if;
        return '0';
    end function;

    function h0_test_2(index : natural) return std_logic is
    begin
        if (index mod 2) = 1 or (index mod 13) = 0 then
            return '1';
        end if;
        return '0';
    end function;
begin
    clk <= not clk after C_CLK_PERIOD / 2;

    dut : entity work.rebuild_s0(rtl)
        generic map (
            g_num_samples => C_NUM_SAMPLES,
            g_data_width  => C_DATA_WIDTH,
            g_addr_width  => C_ADDR_WIDTH
        )
        port map (
            clk            => clk,
            rst_n          => rst_n,
            start          => start,
            data_in_valid  => data_in_valid,
            done           => done,
            data_q00       => data_q00,
            data_q01       => data_q01,
            data_w1        => data_w1,
            data_h0        => data_h0,
            data_out       => data_out,
            data_out_valid => data_out_valid,
            error          => dut_error
        );

    stimulus : process
        variable output_count : natural range 0 to C_NUM_SAMPLES := 0;
        variable saw_done     : boolean := false;
        variable h0_values    : std_logic_vector(C_NUM_SAMPLES - 1 downto 0);
        variable expected     : integer;
        variable obtained     : integer;
    begin
        -----------------------------------------------------------------------
        -- Reset
        -----------------------------------------------------------------------
        rst_n <= '0';
        wait until rising_edge(clk);
        wait until rising_edge(clk);
        rst_n <= '1';
        wait until rising_edge(clk);

        -----------------------------------------------------------------------
        -- Test 1: q00[0]=1, q01=0 and w1=0.
        --
        -- Xre=Xim=0, therefore qhat01=0 and t=IFFT(qhat01)=0.
        -- Since c_s0*h0 is smaller than 2*c_q00, z=0 and w0=h0.
        -----------------------------------------------------------------------
        for i in 0 to C_NUM_SAMPLES - 1 loop
            h0_values(i) := h0_test_1(i);
        end loop;
        data_h0 <= h0_values;

        start <= '1';
        wait until rising_edge(clk);
        start <= '0';

        data_in_valid <= '1';
        for i in 0 to C_NUM_SAMPLES - 1 loop
            if i = 0 then
                data_q00 <= std_logic_vector(to_signed(1, C_DATA_WIDTH));
            else
                data_q00 <= (others => '0');
            end if;
            data_q01 <= (others => '0');
            data_w1  <= (others => '0');
            wait until rising_edge(clk);
        end loop;
        data_in_valid <= '0';

        output_count := 0;
        saw_done := false;
        for cycle in 0 to C_TIMEOUT - 1 loop
            wait until rising_edge(clk);
            wait for 1 ns;

            assert not is_x(data_out_valid)
                report "data_out_valid contiene bits desconocidos"
                severity failure;
            assert not is_x(done)
                report "done contiene bits desconocidos"
                severity failure;
            assert not is_x(dut_error)
                report "error contiene bits desconocidos"
                severity failure;

            if data_out_valid = '1' then
                assert output_count < C_NUM_SAMPLES
                    report "RebuildS0 produjo mas de 512 coeficientes"
                    severity failure;
                assert not is_x(data_out)
                    report "RebuildS0 produjo bits desconocidos en la salida " &
                           integer'image(output_count)
                    severity failure;

                if h0_values(output_count) = '1' then
                    expected := 1;
                else
                    expected := 0;
                end if;
                obtained := to_integer(signed(data_out));

                assert obtained = expected
                    report "Diferencia en prueba 1, indice " &
                           integer'image(output_count) &
                           ": obtenido=" & integer'image(obtained) &
                           ", esperado=" & integer'image(expected)
                    severity failure;

                output_count := output_count + 1;
            end if;

            if done = '1' then
                saw_done := true;
                exit;
            end if;
        end loop;

        assert saw_done
            report "Timeout esperando done en la prueba 1"
            severity failure;
        assert dut_error = '0'
            report "RebuildS0 activo error en una entrada valida"
            severity failure;
        assert output_count = C_NUM_SAMPLES
            report "RebuildS0 produjo " & integer'image(output_count) &
                   " salidas; se esperaban 512"
            severity failure;

        report "Prueba 1 superada: salida w0 igual a h0" severity note;

        wait until rising_edge(clk);
        wait until rising_edge(clk);

        -----------------------------------------------------------------------
        -- Test 2: q00[0] negativo. Debe terminar con error y sin salida.
        -----------------------------------------------------------------------
        data_h0 <= (others => '0');
        start <= '1';
        wait until rising_edge(clk);
        start <= '0';

        data_q00 <= std_logic_vector(to_signed(-1, C_DATA_WIDTH));
        data_q01 <= (others => '0');
        data_w1  <= (others => '0');
        data_in_valid <= '1';
        wait until rising_edge(clk);
        data_in_valid <= '0';

        saw_done := false;
        for cycle in 0 to 20 loop
            wait until rising_edge(clk);
            wait for 1 ns;

            assert data_out_valid = '0'
                report "Se produjo una salida valida despues de q00[0] < 0"
                severity failure;

            if done = '1' then
                assert dut_error = '1'
                    report "done se activo sin error para q00[0] < 0"
                    severity failure;
                saw_done := true;
                exit;
            end if;
        end loop;

        assert saw_done
            report "No se recibio done para q00[0] < 0"
            severity failure;

        report "Prueba 2 superada: deteccion de q00[0] negativo" severity note;

        wait until rising_edge(clk);
        wait until rising_edge(clk);

        -----------------------------------------------------------------------
        -- Test 3: ejecucion valida despues de ST_ERROR. Incluye huecos en
        -- data_in_valid para comprobar que el contador solo consume validos.
        -----------------------------------------------------------------------
        for i in 0 to C_NUM_SAMPLES - 1 loop
            h0_values(i) := h0_test_2(i);
        end loop;
        data_h0 <= h0_values;

        start <= '1';
        wait until rising_edge(clk);
        start <= '0';

        for i in 0 to C_NUM_SAMPLES - 1 loop
            if (i mod 17) = 0 then
                data_in_valid <= '0';
                wait until rising_edge(clk);
            end if;

            if i = 0 then
                data_q00 <= std_logic_vector(to_signed(1, C_DATA_WIDTH));
            else
                data_q00 <= (others => '0');
            end if;
            data_q01 <= (others => '0');
            data_w1  <= (others => '0');
            data_in_valid <= '1';
            wait until rising_edge(clk);
        end loop;
        data_in_valid <= '0';

        output_count := 0;
        saw_done := false;
        for cycle in 0 to C_TIMEOUT - 1 loop
            wait until rising_edge(clk);
            wait for 1 ns;

            if data_out_valid = '1' then
                assert output_count < C_NUM_SAMPLES
                    report "RebuildS0 produjo mas de 512 coeficientes en prueba 3"
                    severity failure;
                assert not is_x(data_out)
                    report "Salida desconocida en prueba 3"
                    severity failure;

                if h0_values(output_count) = '1' then
                    expected := 1;
                else
                    expected := 0;
                end if;
                obtained := to_integer(signed(data_out));

                assert obtained = expected
                    report "Diferencia en prueba 3, indice " &
                           integer'image(output_count) &
                           ": obtenido=" & integer'image(obtained) &
                           ", esperado=" & integer'image(expected)
                    severity failure;

                output_count := output_count + 1;
            end if;

            if done = '1' then
                saw_done := true;
                exit;
            end if;
        end loop;

        assert saw_done
            report "Timeout esperando done en la prueba 3"
            severity failure;
        assert dut_error = '0'
            report "Error inesperado en la ejecucion posterior a ST_ERROR"
            severity failure;
        assert output_count = C_NUM_SAMPLES
            report "La prueba 3 produjo " & integer'image(output_count) &
                   " salidas; se esperaban 512"
            severity failure;

        report "Prueba 3 superada: recuperacion despues de ST_ERROR"
            severity note;

        -- Tests 4..6: dense signed inputs and an independent integer oracle.
        -- 4: constant denominator; 5: nonconstant q00; 6: reversed q01 sign.
        -- Constants include all 512 inputs and exact expected coefficients.
        for test in 0 to 2 loop
            wait until falling_edge(clk);
            for i in 0 to C_NUM_SAMPLES-1 loop
                if C_H0(test)(i) = 1 then
                    h0_values(i) := '1';
                else
                    h0_values(i) := '0';
                end if;
            end loop;
            data_h0 <= h0_values;
            start <= '1';
            wait until falling_edge(clk);
            start <= '0';
            for i in 0 to C_NUM_SAMPLES-1 loop
                if (i mod 17) = 0 or (i mod 31) = 0 then
                    data_in_valid <= '0';
                    -- Poison invalid cycles to expose accidental consumption.
                    data_q00 <= std_logic_vector(to_signed(-77, C_DATA_WIDTH));
                    data_q01 <= std_logic_vector(to_signed(123, C_DATA_WIDTH));
                    data_w1 <= std_logic_vector(to_signed(-321, C_DATA_WIDTH));
                    wait until falling_edge(clk);
                end if;
                data_in_valid <= '1';
                data_q00 <= std_logic_vector(to_signed(C_Q00(test)(i), C_DATA_WIDTH));
                data_q01 <= std_logic_vector(to_signed(C_Q01(test)(i), C_DATA_WIDTH));
                data_w1 <= std_logic_vector(to_signed(C_W1(test)(i), C_DATA_WIDTH));
                wait until rising_edge(clk);
                wait for 1 ns;
                assert done = '0' and data_out_valid = '0' and dut_error = '0'
                    report "Terminacion o salida prematura durante la carga"
                    severity failure;
                wait until falling_edge(clk);
            end loop;
            data_in_valid <= '0';
            output_count := 0;
            saw_done := false;
            for cycle in 0 to C_TIMEOUT-1 loop
                wait until rising_edge(clk);
                wait for 1 ns;
                assert not is_x(data_out_valid) and not is_x(done) and not is_x(dut_error)
                    report "Control desconocido en prueba " & integer'image(test+4) &
                           ": valid=" & std_logic'image(data_out_valid) &
                           ", done=" & std_logic'image(done) &
                           ", error=" & std_logic'image(dut_error)
                    severity failure;
                assert dut_error = '0'
                    report "DUT activo error en prueba " & integer'image(test+4) &
                           ", coeficientes recibidos=" & integer'image(output_count)
                    severity failure;
                if data_out_valid = '1' then
                    assert output_count < C_NUM_SAMPLES
                        report "Demasiados coeficientes" severity failure;
                    assert not is_x(data_out)
                        report "Coeficiente desconocido" severity failure;
                    expected := C_EXPECTED(test)(output_count);
                    obtained := to_integer(signed(data_out));
                    assert obtained = expected
                        report "Diferencia en prueba " & integer'image(test+4) &
                               ", indice " & integer'image(output_count) &
                               ": obtenido=" & integer'image(obtained) &
                               ", esperado=" & integer'image(expected)
                        severity failure;
                    output_count := output_count + 1;
                end if;
                if done = '1' then
                    saw_done := true;
                    exit;
                end if;
            end loop;
            assert saw_done and output_count = C_NUM_SAMPLES
                report "Timeout o numero incorrecto de coeficientes" severity failure;
            for cycle in 1 to 4 loop
                wait until rising_edge(clk);
                wait for 1 ns;
                assert done = '0' and data_out_valid = '0' and dut_error = '0'
                    report "Pulso done repetido o salida despues de done" severity failure;
            end loop;
            report "Prueba " & integer'image(test+4) &
                   " superada: 512 coeficientes iguales al modelo entero" severity note;
        end loop;
        report "Todas las pruebas de RebuildS0 han finalizado correctamente"
            severity note;

        -- finish;
        wait;
    end process stimulus;
end architecture simulation;
